import 'package:flutter/material.dart';
import 'package:flutter_animate/flutter_animate.dart';

class BasicAnimateExample extends StatelessWidget {
  const BasicAnimateExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('기본 애니메이션')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // 페이드 인
            const Text('페이드 인')
                .animate()
                .fadeIn(duration: 600.ms),
            const SizedBox(height: 20),

            // 슬라이드 + 페이드
            const Text('슬라이드 + 페이드')
                .animate()
                .fadeIn()
                .slideX(begin: -0.5, end: 0),
            const SizedBox(height: 20),

            // 스케일
            Container(
              width: 100,
              height: 100,
              color: Colors.blue,
            )
                .animate()
                .scale(begin: const Offset(0.5, 0.5), end: const Offset(1, 1))
                .fadeIn(),
            const SizedBox(height: 20),

            // 회전
            const Icon(Icons.star, size: 50, color: Colors.amber)
                .animate(onPlay: (controller) => controller.repeat())
                .rotate(duration: 2.seconds),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_animate/flutter_animate.dart';

class SequenceAnimateExample extends StatelessWidget {
  const SequenceAnimateExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('순차/동시 애니메이션')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // 순차 애니메이션 (then 사용)
            Container(
              width: 100,
              height: 100,
              color: Colors.blue,
              child: const Center(
                child: Text('순차', style: TextStyle(color: Colors.white)),
              ),
            )
                .animate()
                // 1. 페이드 인
                .fadeIn(duration: 500.ms)
                // 2. 페이드 인 후 스케일 업
                .then(delay: 200.ms)
                .scale(begin: const Offset(1, 1), end: const Offset(1.2, 1.2))
                // 3. 스케일 후 회전
                .then()
                .rotate(begin: 0, end: 0.05)
                // 4. 다시 원래 크기로
                .then()
                .scale(begin: const Offset(1.2, 1.2), end: const Offset(1, 1)),
            const SizedBox(height: 40),

            // 동시 애니메이션 (같은 위치에서 시작)
            Container(
              width: 100,
              height: 100,
              color: Colors.green,
              child: const Center(
                child: Text('동시', style: TextStyle(color: Colors.white)),
              ),
            )
                .animate()
                // 모두 동시에 실행
                .fadeIn(duration: 800.ms)
                .slideY(begin: 0.5, end: 0, duration: 800.ms)
                .scale(
                  begin: const Offset(0.8, 0.8),
                  end: const Offset(1, 1),
                  duration: 800.ms,
                ),
            const SizedBox(height: 40),

            // 지연 시작
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: List.generate(5, (index) {
                return Container(
                  width: 40,
                  height: 40,
                  margin: const EdgeInsets.symmetric(horizontal: 4),
                  decoration: BoxDecoration(
                    color: Colors.primaries[index * 2],
                    borderRadius: BorderRadius.circular(8),
                  ),
                )
                    .animate()
                    .fadeIn(delay: (100 * index).ms)
                    .slideY(begin: 0.5, end: 0, delay: (100 * index).ms);
              }),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_animate/flutter_animate.dart';

class EffectsShowcase extends StatelessWidget {
  const EffectsShowcase({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('이펙트 모음')),
      body: ListView(
        padding: const EdgeInsets.all(16),
        children: [
          // 페이드
          _EffectCard(
            title: 'Fade',
            child: const Icon(Icons.visibility, size: 50)
                .animate(onPlay: (c) => c.repeat(reverse: true))
                .fadeIn(duration: 1.seconds)
                .fadeOut(delay: 1.seconds, duration: 1.seconds),
          ),

          // 슬라이드
          _EffectCard(
            title: 'Slide',
            child: const Icon(Icons.arrow_forward, size: 50)
                .animate(onPlay: (c) => c.repeat(reverse: true))
                .slideX(begin: -0.5, end: 0.5, duration: 1.seconds),
          ),

          // 스케일
          _EffectCard(
            title: 'Scale',
            child: const Icon(Icons.zoom_in, size: 50)
                .animate(onPlay: (c) => c.repeat(reverse: true))
                .scale(
                  begin: const Offset(0.5, 0.5),
                  end: const Offset(1.5, 1.5),
                  duration: 1.seconds,
                ),
          ),

          // 회전
          _EffectCard(
            title: 'Rotate',
            child: const Icon(Icons.refresh, size: 50)
                .animate(onPlay: (c) => c.repeat())
                .rotate(duration: 2.seconds),
          ),

          // 쉐이크
          _EffectCard(
            title: 'Shake',
            child: const Icon(Icons.vibration, size: 50)
                .animate(onPlay: (c) => c.repeat())
                .shake(hz: 4, duration: 1.seconds),
          ),

          // 블러
          _EffectCard(
            title: 'Blur',
            child: const Icon(Icons.blur_on, size: 50)
                .animate(onPlay: (c) => c.repeat(reverse: true))
                .blur(begin: const Offset(0, 0), end: const Offset(5, 5)),
          ),

          // 틴트 (색상 변경)
          _EffectCard(
            title: 'Tint',
            child: const Icon(Icons.color_lens, size: 50)
                .animate(onPlay: (c) => c.repeat(reverse: true))
                .tint(color: Colors.red, duration: 1.seconds),
          ),

          // 새추레이션
          _EffectCard(
            title: 'Saturate',
            child: Container(
              width: 50,
              height: 50,
              decoration: const BoxDecoration(
                gradient: LinearGradient(colors: [Colors.red, Colors.blue]),
              ),
            )
                .animate(onPlay: (c) => c.repeat(reverse: true))
                .saturate(begin: 1, end: 0, duration: 1.seconds),
          ),

          // 플립
          _EffectCard(
            title: 'Flip',
            child: const Icon(Icons.flip, size: 50)
                .animate(onPlay: (c) => c.repeat())
                .flipH(duration: 1.seconds),
          ),

          // 쉬머
          _EffectCard(
            title: 'Shimmer',
            child: Container(
              width: 100,
              height: 50,
              color: Colors.grey[300],
            )
                .animate(onPlay: (c) => c.repeat())
                .shimmer(duration: 1.5.seconds),
          ),
        ],
      ),
    );
  }
}

class _EffectCard extends StatelessWidget {
  final String title;
  final Widget child;

  const _EffectCard({required this.title, required this.child});

  @override
  Widget build(BuildContext context) {
    return Card(
      margin: const EdgeInsets.only(bottom: 16),
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Row(
          children: [
            SizedBox(width: 100, child: Text(title)),
            Expanded(child: Center(child: child)),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_animate/flutter_animate.dart';

class ListAnimationExample extends StatelessWidget {
  const ListAnimationExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('리스트 애니메이션')),
      body: ListView.builder(
        padding: const EdgeInsets.all(16),
        itemCount: 10,
        itemBuilder: (context, index) {
          return Card(
            child: ListTile(
              leading: CircleAvatar(
                child: Text('${index + 1}'),
              ),
              title: Text('아이템 ${index + 1}'),
              subtitle: const Text('설명 텍스트'),
              trailing: const Icon(Icons.chevron_right),
            ),
          )
              .animate()
              .fadeIn(delay: (50 * index).ms, duration: 400.ms)
              .slideX(begin: 0.2, end: 0, delay: (50 * index).ms);
        },
      ),
    );
  }
}

// 로그인 화면 애니메이션
class AnimatedLoginScreen extends StatelessWidget {
  const AnimatedLoginScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              // 로고
              const Icon(Icons.flutter_dash, size: 100, color: Colors.blue)
                  .animate()
                  .fadeIn(duration: 600.ms)
                  .scale(begin: const Offset(0.5, 0.5), end: const Offset(1, 1)),
              const SizedBox(height: 48),

              // 이메일 필드
              TextField(
                decoration: const InputDecoration(
                  labelText: '이메일',
                  prefixIcon: Icon(Icons.email),
                  border: OutlineInputBorder(),
                ),
              )
                  .animate()
                  .fadeIn(delay: 200.ms, duration: 400.ms)
                  .slideY(begin: 0.2, end: 0),
              const SizedBox(height: 16),

              // 비밀번호 필드
              TextField(
                obscureText: true,
                decoration: const InputDecoration(
                  labelText: '비밀번호',
                  prefixIcon: Icon(Icons.lock),
                  border: OutlineInputBorder(),
                ),
              )
                  .animate()
                  .fadeIn(delay: 300.ms, duration: 400.ms)
                  .slideY(begin: 0.2, end: 0),
              const SizedBox(height: 24),

              // 로그인 버튼
              SizedBox(
                width: double.infinity,
                height: 48,
                child: ElevatedButton(
                  onPressed: () {},
                  child: const Text('로그인'),
                ),
              )
                  .animate()
                  .fadeIn(delay: 400.ms, duration: 400.ms)
                  .slideY(begin: 0.2, end: 0),
              const SizedBox(height: 16),

              // 회원가입 링크
              TextButton(
                onPressed: () {},
                child: const Text('계정이 없으신가요? 회원가입'),
              )
                  .animate()
                  .fadeIn(delay: 500.ms, duration: 400.ms),
            ],
          ),
        ),
      ),
    );
  }
}

// 성공 애니메이션
class SuccessAnimation extends StatelessWidget {
  const SuccessAnimation({super.key});

  @override
  Widget build(BuildContext context) {
    return Container(
      width: 100,
      height: 100,
      decoration: const BoxDecoration(
        color: Colors.green,
        shape: BoxShape.circle,
      ),
      child: const Icon(Icons.check, color: Colors.white, size: 60),
    )
        .animate()
        .scale(
          begin: const Offset(0, 0),
          end: const Offset(1, 1),
          duration: 400.ms,
          curve: Curves.elasticOut,
        )
        .then()
        .shake(hz: 2, offset: const Offset(0, 5), duration: 400.ms);
  }
}
